.ms-si{display:flex;flex-direction:column;align-items:center;justify-content:center;width:48px;height:48px;border-radius:7px;background:linear-gradient(135deg,#1e3a5f,#1a2744);border:2px solid #3b82f6;animation:msUp .3s}
.ms-si .sv{font-size:1rem;font-weight:700;color:#93c5fd;font-family:monospace}.ms-si .si{font-size:.55rem;color:#64748b}
