.ms-rc .rv{font-family:monospace;font-size:.95rem;font-weight:700;color:#555}.ms-rc .ri{font-size:.55rem;color:#444}
.ms-rc.fl{border-color:#34d399;background:#0f2922}.ms-rc.fl .rv{color:#6ee7b7}
