body.nova-loading-active {
  overflow:hidden;
}

.nova-page-loading {
  position:fixed;
  z-index:2147483000;
  inset:0;
  display:flex;
  width:100%;
  height:100%;
  align-items:center;
  justify-content:center;
  visibility:hidden;
  opacity:0;
  background:#0d1b29;
  transform:scale(1.01);
  transition:opacity 180ms ease,visibility 0s linear 180ms,transform 180ms ease;
  pointer-events:none;
  isolation:isolate;
}

.nova-page-loading.is-visible {
  visibility:visible;
  opacity:1;
  transform:scale(1);
  transition:opacity 160ms ease,transform 160ms ease;
  pointer-events:auto;
}

.nova-page-loading.is-leaving {
  visibility:hidden;
  opacity:0;
  transform:scale(.995);
  transition:opacity 180ms ease,visibility 0s linear 180ms,transform 180ms ease;
  pointer-events:none;
}

.nova-page-loading__inner {
  position:relative;
  z-index:1;
  display:flex;
  max-width:calc(100vw - 40px);
  align-items:center;
  flex-direction:column;
  text-align:center;
  opacity:1;
  transform:scale(1);
  transition:opacity 180ms ease,transform 180ms ease;
}

.nova-page-loading.is-leaving .nova-page-loading__inner {
  opacity:0;
  transform:translateY(-2px) scale(.985);
}

.nova-page-loading__mark {
  position:relative;
  display:block;
  width:310px;
  height:62px;
  flex:none;
}

.nova-page-loading__mark::before,
.nova-page-loading__mark::after {
  position:absolute;
  inset:0;
  border-radius:50%;
  content:"";
}

.nova-page-loading__mark::before {
  inset:30px 0 auto;
  height:1px;
  border:0;
  border-radius:0;
  background:linear-gradient(90deg,transparent,rgba(214,229,237,.18) 18%,rgba(214,229,237,.52) 50%,rgba(214,229,237,.18) 82%,transparent);
  box-shadow:none;
  animation:none;
}

.nova-page-loading__mark::after {
  inset:10px auto auto 50%;
  width:40px;
  height:40px;
  margin-left:-20px;
  border:1px solid transparent;
  border-top-color:rgba(214,229,237,.5);
  border-right-color:rgba(214,229,237,.13);
  animation:nova-loading-turn 2.8s linear infinite;
}

.nova-page-loading__inner strong {
  margin-top:16px;
  color:rgba(239,245,248,.9);
  font:400 1.7rem/1.2 "Cormorant Garamond",Georgia,serif;
  letter-spacing:.42em;
}

.nova-page-loading__inner small {
  margin-top:23px;
  color:rgba(224,235,241,.68);
  font-size:.82rem;
  letter-spacing:.12em;
}

@keyframes nova-loading-turn {
  to {
    transform:rotate(360deg);
  }
}

@media (max-width:480px) {
  .nova-page-loading__mark {
    width:min(310px,calc(100vw - 56px));
    height:58px;
  }
  .nova-page-loading__inner strong {
    margin-top:14px;
    font-size:1.35rem;
    letter-spacing:.32em;
  }
  .nova-page-loading__inner small {
    font-size:.58rem;
    letter-spacing:.18em;
  }
}

@media (prefers-reduced-motion:reduce) {
  .nova-page-loading {
    transition:opacity 180ms ease,visibility 0s linear 180ms;
  }
  .nova-page-loading.is-visible {
    transition:opacity 120ms ease;
  }
  .nova-page-loading__inner {
    transition-duration:120ms;
  }
  .nova-page-loading__mark::before,
  .nova-page-loading__mark::after {
    animation:none;
  }
  .nova-page-loading__mark::after {
    transform:rotate(38deg);
  }
