 [data-home-mode=developer]{--developer-gap:clamp(70px,5vw,96px);display:grid;grid-template-columns:minmax(0,580px) minmax(0,420px);column-gap:var(--developer-gap);align-content:start;align-items:start;justify-content:center;padding:clamp(86px,10svh,112px) clamp(100px,7vw,140px) 40px clamp(274px,18vw,345px)}
 [data-home-mode=developer] .coast-sidebar{width:clamp(200px,11vw,210px)}
