 [data-home-mode=developer]{height:auto;min-height:100svh;padding:0 24px 145px;background:rgba(13,29,41,.28)}
 [data-home-mode=developer] .coast-sidebar{position:relative;top:auto;left:auto;right:auto;width:auto;margin:80px -8px 0;padding:18px 16px;border-color:rgba(216,229,238,.15)}
 [data-home-mode=developer] .coast-brand h1,[data-home-mode=developer] .coast-brand-name{font-size:30px}
 [data-home-mode=developer] .coast-brand p{font-size:11px}
 [data-home-mode=developer] .coast-nav{gap:8px;margin-top:14px}
 [data-home-mode=developer] .coast-nav a{min-height:44px}
 [data-home-mode=developer] .coast-intro{position:relative;left:auto;top:auto;width:auto;max-width:none;margin:40px 0}
