    const stopSnow = window.__fliexSnow.mount(root)
    on(root.querySelector('[data-coast-search]'), 'click', () => window.__fliexOpenSearch?.())
    on(root.querySelector('[data-coast-theme]'), 'click', () => {
      const dark = document.documentElement.getAttribute('data-theme') === 'dark'
      if (window.btf?.activateDarkMode && window.btf?.activateLightMode) {
        if (dark) window.btf.activateLightMode(); else window.btf.activateDarkMode()
        window.btf.saveToLocal?.set('theme', dark ? 'light' : 'dark', 2)
      } else document.documentElement.setAttribute('data-theme', dark ? 'light' : 'dark')
    })
    const renderMusic = () => {
      const state = window.__fliexMusic?.snapshot()
      if (!state) return
      root.querySelectorAll('[data-music-title]').forEach(el => { el.textContent = state.song?.name || '' })
      root.querySelectorAll('[data-music-artist]').forEach(el => { el.textContent = state.song?.artist || '' })
      root.querySelectorAll('[data-music-summary]').forEach(el => { el.textContent = state.playing ? 'MUSIC / PLAYING' : state.ready || state.configured ? 'MUSIC / PAUSED' : 'MUSIC' })
      root.querySelectorAll('[data-music-toggle]').forEach(el => {
        el.disabled = false
        el.title = ''
        el.setAttribute('aria-label', state.playing ? '暂停音乐' : '播放音乐')
        el.innerHTML = ''
      })
      const progress = state.duration ? Math.min(100, state.currentTime / state.duration * 100) : 0
      root.querySelector('[data-music-progress]').style.width = progress + '%'
      root.querySelector('.coast-progress').setAttribute('aria-valuenow', String(Math.round(progress)))
      const retry = root.querySelector('[data-music-retry]')
      retry.hidden = !state.failed
      retry.textContent = state.failed ? '音乐暂时不可用 · 重试' : '重试'
      root.querySelector('[data-music-loading]').hidden = state.ready || state.failed || state.configured
      root.querySelector('.coast-music-info').hidden = !state.ready
    }
    on(document, 'fliex:music', renderMusic)
    root.querySelectorAll('[data-music-toggle]').forEach(el => on(el, 'click', () => window.__fliexMusic?.toggle()))
    on(root.querySelector('[data-music-retry]'), 'click', () => window.__fliexMusic?.retry())
    cleanup = () => { stopSnow(); listeners.splice(0).forEach(off => off()); delete root.dataset.ready }
    renderMusic()
    window.__fliexMusic?.load()
  }
  window.__novaHomeBootstrap = { init, destroy, get running() { return window.__fliexSnow.running } }
  document.addEventListener('pjax:send', destroy)
  document.addEventListener('pjax:complete', init)
  document.addEventListener('pjax:error', init)
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true })
  else init()
})()

(() => {
  'use strict'
  if (window.__fliexNotesIndex) { window.__fliexNotesIndex.init(); return }
  let cleanup = () => {}
  const PAGE_SIZE = 12

  const init = () => {
    const root = document.querySelector('.nova-notes-index')
    if (!root || root.dataset.ready) return
    cleanup()
    root.dataset.ready = 'true'

    const listeners = []
    const on = (target, event, fn) => { if (!target) return; target.addEventListener(event, fn); listeners.push(() => target.removeEventListener(event, fn)) }

    const input = root.querySelector('[data-notes-search]')
    const clearButton = root.querySelector('[data-notes-clear]')
    const filters = root.querySelector('[data-notes-filters]')
    const chips = filters ? [...filters.querySelectorAll('[data-filter]')] : []
    const rows = [...root.querySelectorAll('.nova-note-row')]
    const yearSections = [...root.querySelectorAll('[data-notes-year]')]
    const moreButton = root.querySelector('[data-notes-more]')
    const countLabel = root.querySelector('[data-notes-count]')
    const emptyMessage = root.querySelector('[data-notes-empty]')

    const state = { query: '', category: 'all', limit: PAGE_SIZE }
    let debounce = 0

    const isFiltered = () => Boolean(state.query.trim()) || state.category !== 'all'

    const apply = () => {
      const query = state.query.trim().toLowerCase()
      const matches = rows.map(row => {
        const inCategory = state.category === 'all' || row.dataset.category === state.category
        const inQuery = !query || (row.dataset.search || '').includes(query)
        return inCategory && inQuery
      })

      let visible = 0
      let limitedVisible = 0
      rows.forEach((row, index) => {
        if (!matches[index]) { row.hidden = true; return }
        visible += 1
        // Progressive disclosure only applies to the unfiltered archive.
        if (!isFiltered() && visible > state.limit) { row.hidden = true; return }
        row.hidden = false
        limitedVisible = visible
      })

      const shownCount = isFiltered() ? visible : limitedVisible
      yearSections.forEach(section => {
        const hasVisible = section.querySelectorAll('.nova-note-row:not([hidden])').length > 0
        section.hidden = !hasVisible
      })

      if (countLabel) countLabel.textContent = shownCount + (query || state.category !== 'all' ? ' MATCHES' : ' NOTES')
      if (emptyMessage) emptyMessage.hidden = shownCount > 0
      if (clearButton) clearButton.hidden = !state.query
      if (moreButton) {
        const remaining = isFiltered() ? 0 : Math.max(0, visible - limitedVisible)
        moreButton.hidden = remaining === 0
        if (remaining) moreButton.textContent = 'LOAD MORE · ' + remaining
      }
    }

    const revealAnchor = () => {
      const id = decodeURIComponent(location.hash.slice(1))
      if (!id.startsWith('notes-month-')) return
      const target = document.getElementById(id)
      const index = target ? rows.indexOf(target) : -1
      if (index >= 0 && target.hidden) {
        state.limit = Math.max(state.limit, index + 1)
        apply()
      }
    }

    const commitQuery = () => {
      state.query = input?.value || ''
      apply()
    }

    if (input) {
      on(input, 'input', () => {
        window.clearTimeout(debounce)
        debounce = window.setTimeout(commitQuery, 120)
      })
      on(input, 'keydown', event => {
        if (event.key === 'Escape' && input.value) {
          input.value = ''
          window.clearTimeout(debounce)
          commitQuery()
        }
      })
      on(input, 'search', commitQuery)
    }
    on(clearButton, 'click', () => {
      if (input) { input.value = ''; input.focus() }
      window.clearTimeout(debounce)
      commitQuery()
    })
    chips.forEach(chip => on(chip, 'click', () => {
      state.category = chip.dataset.filter || 'all'
      chips.forEach(item => item.setAttribute('aria-pressed', String(item === chip)))
      apply()
    }))
    on(moreButton, 'click', () => {
      state.limit += PAGE_SIZE
      apply()
      const next = root.querySelector('.nova-note-row[hidden]')
      if (next) { next.scrollIntoView({ block: 'center', behavior: 'instant' }) }
    })
    on(window, 'hashchange', revealAnchor)

    apply()
    revealAnchor()

    cleanup = () => {
      window.clearTimeout(debounce)
      listeners.splice(0).forEach(off => off())
      delete root.dataset.ready
    }
  }

  window.__fliexNotesIndex = { init }
  document.addEventListener('pjax:send', () => cleanup())
  document.addEventListener('pjax:complete', init)
  document.addEventListener('pjax:error', init)
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true })
  else init()
})()

(() => {
  'use strict'

  if (window.__novaUxReady) return
  window.__novaUxReady = true

  const INITIAL_MIN_DURATION = 150
  const INITIAL_MAX_DURATION = 2000
  const EXIT_DURATION = 180
  const ROUTE_CLASSES = [
    'nova-home-active',
    'nova-music-route',
    'nova-about-route',
    'nova-notes-route',
    'nova-notes-index-route',
    'nova-projects-route',
    'article-sea-route',
  ]
  let initialFinishTimer = 0
  let initialFallbackTimer = 0
  let removeTimer = 0
  let initialFinishScheduled = false
  let statsTimer = 0
  let navigationObserver = null
  let searchObserver = null

  function getLoader() {
    const loaders = Array.from(document.querySelectorAll('[data-nova-loading]'))
    let loader = loaders.shift()
    loaders.forEach(item => item.remove())
    if (loader) return loader

    loader = document.createElement('div')
    loader.className = 'nova-page-loading'
    loader.dataset.novaLoading = ''
    loader.setAttribute('aria-hidden', 'true')
    loader.innerHTML = `


        FLIEX
        正在加载...
      `
    document.body.appendChild(loader)
    return loader
  }

  function enhanceSearch() {
    const dialog = document.querySelector('#local-search .search-dialog')
    const input = dialog?.querySelector('.local-search-input input')
    const results = dialog?.querySelector('#local-search-results')
    if (!dialog || !input || !results || dialog.dataset.novaSearchReady === 'true') return
    dialog.dataset.novaSearchReady = 'true'

    searchObserver?.disconnect()
    searchObserver = null

    const state = document.createElement('div')
    state.className = 'nova-search-state'
    state.innerHTML = `
      QUICK PASSAGE
      从这里进入夜航档案
      输入关键词，或先浏览常用页面。

        笔记
        关于
        项目
        音乐
      `
    results.before(state)

    const renderState = () => {
      const query = input.value.trim()
      const hasResults = Boolean(results.querySelector('.local-search-hit-item'))
      state.hidden = Boolean(query && hasResults)
      state.classList.toggle('is-empty-result', Boolean(query && !hasResults))
      if (query && !hasResults) {
        state.querySelector('.nova-search-state__eyebrow').textContent = 'NO SIGNAL'
        state.querySelector('strong').textContent = '没有找到相关记录'
        state.querySelector('p').textContent = '换一个更短的关键词，或从快速入口继续浏览。'
      } else {
        state.querySelector('.nova-search-state__eyebrow').textContent = 'QUICK PASSAGE'
        state.querySelector('strong').textContent = '从这里进入夜航档案'
        state.querySelector('p').textContent = '输入关键词，或先浏览常用页面。'
      }
    }

    input.addEventListener('input', () => window.setTimeout(renderState, 0))
    searchObserver = new MutationObserver(renderState)
    searchObserver.observe(results, { childList: true, subtree: true })
    renderState()
  }

  function cleanupSearch() {
    searchObserver?.disconnect()
    searchObserver = null
  }

  function finishInitialLoading() {
    window.clearTimeout(window.__novaLoaderDelayTimer)
    window.__novaLoaderDelayTimer = 0
    const loader = document.querySelector('[data-nova-loading]')
    if (!loader) {
      document.body.classList.remove('nova-loading-active')
      return
    }
    if (loader.dataset.novaLoadingState === 'leaving') return

    if (!loader.classList.contains('is-visible')) {
      window.clearTimeout(initialFinishTimer)
      window.clearTimeout(initialFallbackTimer)
      window.clearTimeout(removeTimer)
      loader.remove()
      document.body.classList.remove('nova-loading-active')
      return
    }

    loader.dataset.novaLoadingState = 'leaving'
    loader.setAttribute('aria-hidden', 'true')
    loader.classList.add('is-leaving')
    loader.classList.remove('is-visible')
    window.clearTimeout(initialFinishTimer)
    window.clearTimeout(initialFallbackTimer)
    window.clearTimeout(removeTimer)
    removeTimer = window.setTimeout(() => {
      loader.remove()
      document.body.classList.remove('nova-loading-active')
    }, EXIT_DURATION)
  }

  function scheduleInitialFinish() {
    if (initialFinishScheduled) return
    initialFinishScheduled = true
    window.clearTimeout(window.__novaLoaderDelayTimer)
    window.__novaLoaderDelayTimer = 0
    const loader = document.querySelector('[data-nova-loading]')
    if (!loader?.classList.contains('is-visible')) {
      finishInitialLoading()
      return
    }
    const visibleAt = Number(window.__novaLoaderVisibleAt) || Date.now()
    const elapsed = Date.now() - visibleAt
    initialFinishTimer = window.setTimeout(
      finishInitialLoading,
      Math.max(0, INITIAL_MIN_DURATION - elapsed)
    )
  }

  function initInitialLoading() {
    const loader = getLoader()
    loader.classList.remove('is-leaving')
    if (loader.classList.contains('is-visible')) {
      loader.dataset.novaLoadingState = 'visible'
      loader.setAttribute('aria-hidden', 'false')
      document.body.classList.add('nova-loading-active')
    } else {
      loader.dataset.novaLoadingState = 'pending'
      loader.setAttribute('aria-hidden', 'true')
      document.body.classList.remove('nova-loading-active')
    }

    initialFallbackTimer = window.setTimeout(finishInitialLoading, INITIAL_MAX_DURATION)
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', scheduleInitialFinish, { once: true })
    } else {
      scheduleInitialFinish()
    }
  }

  function beginNavigation() {
    cleanupSearch()
    finishInitialLoading()
  }

  function finishNavigation() {
    syncRouteState()
    finishInitialLoading()
  }

  function initStatsFallback() {
    window.clearTimeout(statsTimer)
    const targets = [
      document.getElementById('busuanzi_value_site_uv'),
      document.getElementById('busuanzi_value_site_pv'),
      document.getElementById('last-push-date')
    ].filter(Boolean)
    if (!targets.length) return

    statsTimer = window.setTimeout(() => {
      targets.forEach(target => {
        if (!target.isConnected || !target.querySelector('.fa-spinner')) return
        target.textContent = '—'
        target.title = '统计服务暂时不可用'
      })
    }, 9000)
  }

  function syncNavigationSemantics() {
    const desktopMenu = document.getElementById('menus')
    const desktopMenuItems = desktopMenu?.querySelector('.menus_items')
    const mobileMenu = document.getElementById('sidebar-menus')
    const isMobile = window.matchMedia('(max-width: 768px)').matches
    const mobileMenuOpen = Boolean(isMobile && mobileMenu?.classList.contains('open'))

    if (desktopMenu) {
      desktopMenu.inert = false
      desktopMenu.removeAttribute('aria-hidden')
    }
    if (desktopMenuItems) {
      desktopMenuItems.inert = isMobile
      desktopMenuItems.setAttribute('aria-hidden', String(isMobile))
    }
    if (mobileMenu) {
      mobileMenu.inert = !mobileMenuOpen
      mobileMenu.setAttribute('aria-hidden', String(!mobileMenuOpen))
    }

    navigationObserver?.disconnect()
    if (mobileMenu) {
      navigationObserver = new MutationObserver(syncNavigationSemantics)
      navigationObserver.observe(mobileMenu, { attributes: true, attributeFilter: ['class'] })
    }
  }

  function syncRouteState() {
    document.body.classList.remove(...ROUTE_CLASSES)
    const routeMarkers = [
      ['.nova-music-page', ['nova-music-route']],
      ['.nova-about-shell', ['nova-about-route']],
      ['.nova-notes-index', ['nova-notes-route', 'nova-notes-index-route']],
      ['.nova-projects-content', ['nova-notes-route', 'nova-projects-route']],
      ['.nova-notes-shell', ['nova-notes-route']],
      ['.article-reading-shell', ['article-sea-route']],
      ['.coast-home[data-nova-home]', ['nova-home-active']],
      ['.archive-home[data-nova-home]', ['nova-home-active']],
      ['.nova-about-page', ['nova-about-route']],
    ]
    const match = routeMarkers.find(([selector]) => document.querySelector(selector))
    if (match) document.body.classList.add(...match[1])
  }

  document.addEventListener('pjax:send', beginNavigation)
  document.addEventListener('pjax:complete', finishNavigation)
  document.addEventListener('pjax:error', finishNavigation)
  document.addEventListener('DOMContentLoaded', enhanceSearch, { once: true })
  document.addEventListener('DOMContentLoaded', initStatsFallback, { once: true })
  document.addEventListener('DOMContentLoaded', syncNavigationSemantics, { once: true })
  document.addEventListener('DOMContentLoaded', syncRouteState, { once: true })
  document.addEventListener('pjax:complete', enhanceSearch)
  document.addEventListener('pjax:complete', initStatsFallback)
  document.addEventListener('pjax:complete', syncNavigationSemantics)
  document.addEventListener('pjax:complete', syncRouteState)
  window.addEventListener('pageshow', finishInitialLoading)
  window.addEventListener('pageshow', scheduleInitialFinish, { once: true })
  window.addEventListener('resize', syncNavigationSemantics)
  initInitialLoading()
  if (document.readyState !== 'loading') {
    enhanceSearch()
    initStatsFallback()
    syncNavigationSemantics()
    syncRouteState()
  }
})()

(() => {
  'use strict'
  if (window.__fliexProjectPreview) { window.__fliexProjectPreview.init(); return }
  let cleanup = () => {}, live = null
  const restore = (style, name, value) => value ? style.setProperty(name, value) : style.removeProperty(name)
  const stroke = body => `${body}`
  const icons = {
    back: stroke(''),
    desktop: stroke(''),
    tablet: stroke(''),
    mobile: stroke(''),
    refresh: stroke(''),
    external: stroke(''),
    github: '',
    fullscreen: stroke(''),
    close: stroke('')
  }
  const close = ({returnFocus = true} = {}) => {
    const session = live
    if (!session) return
    live = null
    session.run++
    session.abort?.abort()
    clearTimeout(session.timer)
    clearTimeout(session.soft)
    session.frame?.remove()
    session.frame = null
    session.removeListeners?.()
    if (document.fullscreenElement === session.dialog) document.exitFullscreen?.().catch(() => {})
    if (session.dialog.open && session.dialog.close) session.dialog.close()
    session.dialog.remove()
    restore(document.body.style, 'overflow', session.bodyOverflow)
    restore(document.documentElement.style, 'overflow', session.htmlOverflow)
    if (returnFocus) {
      const behavior = document.documentElement.style.scrollBehavior
      document.documentElement.style.scrollBehavior = 'auto'
      window.scrollTo(session.x, session.y)
      restore(document.documentElement.style, 'scroll-behavior', behavior)
      if (session.trigger?.isConnected) session.trigger.focus({preventScroll:true})
    }
  }
  const destroy = () => { close({returnFocus:false}); cleanup(); cleanup = () => {} }
  const init = () => {
    const root = document.querySelector('[data-projects-switcher]')
    const source = document.querySelector('[data-project-preview-config]')
    if (!root || !source || root.dataset.previewReady) return
    destroy()
    let config
    try { config = JSON.parse(source.textContent) } catch { return }
    Object.values(config).forEach(project => {
      project.works = (project.works || []).filter(work => {
        try {
          const url = new URL(work.demoUrl)
          return url.origin === 'https://novafliex.github.io' && url.pathname.startsWith('/' + project.name + '/') && !url.username && !url.password
        } catch { return false }
      })
    })
    root.dataset.previewReady = 'true'
    const listeners = []
    const on = (target, type, fn) => { target.addEventListener(type, fn); listeners.push(() => target.removeEventListener(type, fn)) }
    const open = (key, trigger) => {
      const project = config[key]
      if (!project?.works.length || live) return
      // Work selection belongs to the Projects list; the shell only receives the chosen id.
      const work = project.works.find(item => item.id === trigger?.dataset.openWork) || project.works[0]
      const dialog = document.createElement('dialog')
      dialog.className = 'project-preview-dialog'
      dialog.setAttribute('aria-labelledby', 'project-preview-title')
      dialog.setAttribute('aria-modal', 'true')
      dialog.innerHTML = `
        ${icons.back}PROJECTS · 


        ${icons.desktop}${icons.tablet}${icons.mobile}

        ${icons.refresh}${icons.external}${icons.github}${icons.fullscreen}${icons.close}


        LOADING重试继续查看独立打开项目 ↗返回 Projects
      `
      const session = live = {
        dialog, trigger, project, work:null, frame:null, abort:null, timer:0, run:0, soft:0,
        x:window.scrollX, y:window.scrollY, bodyOverflow:document.body.style.overflow,
        htmlOverflow:document.documentElement.style.overflow
      }
      document.body.appendChild(dialog)
      const viewport = dialog.querySelector('[data-preview-viewport]')
      const notice = dialog.querySelector('[data-preview-notice]')
      const message = dialog.querySelector('[data-preview-message]')
      const detail = dialog.querySelector('[data-preview-detail]')
      const recovery = dialog.querySelector('[data-preview-recovery]')
      const continueButton = dialog.querySelector('[data-preview-continue]')
      const status = dialog.querySelector('[data-preview-status]')
      const kicker = dialog.querySelector('[data-preview-kicker]')
      const counter = dialog.querySelector('[data-preview-counter]')
      const setState = state => { notice.dataset.state = state; kicker.textContent = state === 'error' ? 'UNAVAILABLE' : state === 'unverified' ? 'UNVERIFIED' : 'LOADING' }
      dialog.querySelector('[data-preview-project]').textContent = project.name
      const current = version => live === session && session.run === version
      const fail = (version, reason) => {
        if (!current(version)) return
        session.run++
        session.abort?.abort()
        clearTimeout(session.timer)
        session.frame?.remove(); session.frame = null
        notice.hidden = false
        setState('error')
        message.textContent = '预览暂时无法加载'
        detail.textContent = reason
        recovery.hidden = false
        continueButton.hidden = true
        status.textContent = '可重试、独立打开项目，或返回 Projects。'
      }
      const load = work => {
        session.abort?.abort()
        clearTimeout(session.timer)
        clearTimeout(session.soft)
        session.soft = 0
        session.frame?.remove()
        session.frame = null
        session.work = work
        const version = ++session.run
        const abort = session.abort = new AbortController()
        let responded = false, verified = false, uncertain = false, bridgeReady = !work.previewBridge, resourceWarning = false
        const token = work.previewBridge ? [...crypto.getRandomValues(new Uint32Array(4))].map(value => value.toString(16).padStart(8,'0')).join('') : ''
        notice.hidden = false
        setState('loading')
        recovery.hidden = true
        continueButton.hidden = true
        message.textContent = work.name
        detail.textContent = '正在检查部署页面和必要资源。'
        status.textContent = '隔离加载中；第三方资源和音频可用性取决于项目及网络。'
        dialog.querySelector('#project-preview-title').textContent = work.name
        counter.hidden = project.works.length < 2
        counter.textContent = ' · ' + String(project.works.indexOf(work) + 1).padStart(2, '0') + ' / ' + String(project.works.length).padStart(2, '0')
        dialog.querySelectorAll('[data-preview-external]').forEach(a => { a.href = work.demoUrl })
        const code = dialog.querySelector('[data-preview-source]')
        code.hidden = !/^https:\/\/github\.com\//.test(work.githubUrl || '')
        if (!code.hidden) code.href = work.githubUrl
        const check = () => {
          if (!current(version) || !responded || !bridgeReady || (!verified && !uncertain)) return
          clearTimeout(session.timer)
          if (verified) {
            notice.hidden = true
            status.textContent = work.previewBridge
              ? resourceWarning ? '页面已初始化，但部分资源加载异常；可重试或独立打开。' : '页面初始化与必要资源已确认 · 独立沙箱预览'
              : '页面与必要资源已验证；隔离内容无法自动确认，画面异常时可独立打开。'
          } else if (work.previewBridge && bridgeReady) {
            notice.hidden = true
            status.textContent = '页面初始化已确认，但资源响应未能完全核验；画面异常时可重试。'
          } else {
            message.textContent = '无法确认预览加载状态'
            detail.textContent = '浏览器或网络限制了资源验证。可继续目视查看隔离页面，或独立打开。'
            recovery.hidden = false
            continueButton.hidden = false
            setState('unverified')
            status.textContent = '尚未确认预览内容；没有将 iframe 响应当作加载成功。'
          }
        }
        // Some browsers throttle rAF inside sandboxed frames, so a fully verified
        // bridge work may never emit its runtime signal. Deployment facts were all
        // confirmed parent-side; fall back to them instead of timing out.
        const softAccept = () => {
          if (!current(version) || notice.hidden || !session.frame) return
          notice.hidden = true
          status.textContent = '页面与必要资源已验证；沙箱内运行信号未回传（可能被浏览器节流），画面异常时可重试或独立打开。'
        }
        const frame = session.frame = document.createElement('iframe')
        frame.title = work.name + ' 交互预览'
        // Opaque origin even on production, where project Pages shares the blog origin.
        // Do not combine allow-scripts with allow-same-origin here.
        frame.setAttribute('sandbox', 'allow-scripts allow-popups')
        frame.setAttribute('allow', 'autoplay')
        frame.referrerPolicy = 'no-referrer'
        frame.addEventListener('load', () => { if (current(version)) { responded = true; check() } })
        frame.addEventListener('error', () => fail(version, '网络或浏览器嵌入限制阻止了页面加载。'))
        session.onMessage = event => {
          const data = event.data
          // A sandboxed sender has origin "null". Bind to its WindowProxy and a
          // per-load nonce instead of trusting an origin string or message alone.
          if (!current(version) || !work.previewBridge || event.source !== frame.contentWindow || data?.channel !== 'fliex-preview' || data.token !== token) return
          if (data.type === 'escape') { escapePreview(); return }
          if (data.type === 'resource-error') {
            resourceWarning = true
            if (notice.hidden) status.textContent = '部分项目资源未能加载；可重试或独立打开。'
          }
          if (data.type === 'ready') {
            if ((work.expectedTitle && data.title !== work.expectedTitle) || ((work.expectedSelectors || []).includes('#hero-galaxy-canvas') && !data.canvasReady)) {
              fail(version, '项目页面尚未正确初始化，请重试或独立打开。'); return
            }
            bridgeReady = true
            responded = true
            resourceWarning ||= Array.isArray(data.missingResources) && data.missingResources.length > 0
            check()
          }
        }
        const frameUrl = new URL(work.demoUrl)
        if (work.previewBridge) {
          frameUrl.searchParams.set('fliex-preview', token)
          frameUrl.searchParams.set('fliex-parent', location.origin)
        }
        frame.src = frameUrl.href
        viewport.appendChild(frame)
        session.timer = setTimeout(() => {
          if (responded && verified) softAccept()
          else fail(version, '等待时间过长，可能存在网络、部署或嵌入限制。')
        }, 18000)
        ;(async () => {
          try {
            const response = await fetch(work.demoUrl, {signal:abort.signal,credentials:'omit',cache:'no-store'})
            if (!current(version)) return
            if (!response.ok) { fail(version, '部署页面返回 HTTP ' + response.status + '，请检查 GitHub Pages。'); return }
            if (/DENY/i.test(response.headers.get('x-frame-options') || '') || /frame-ancestors\s+'none'/i.test(response.headers.get('content-security-policy') || '')) {
              fail(version, '项目服务器禁止页面被嵌入，请独立打开项目。'); return
            }
            const html = new DOMParser().parseFromString(await response.text(), 'text/html')
            if ((work.expectedTitle && html.title.trim() !== work.expectedTitle) || (work.expectedSelectors || []).some(selector => !html.querySelector(selector))) {
              fail(version, '返回的页面与项目入口不符，可能尚未正确部署。'); return
            }
            const assets = (work.requiredAssets || []).filter(asset => /^[\w./-]+$/.test(asset) && !asset.includes('..') && !asset.startsWith('/'))
            const responses = await Promise.all(assets.map(asset => fetch(new URL(asset, work.demoUrl).href, {method:'HEAD',signal:abort.signal,credentials:'omit',cache:'no-store'})))
            if (!current(version)) return
            if (responses.some(result => !result.ok)) { fail(version, '部分必要的 CSS、脚本或图片资源无法加载。'); return }
            verified = true
            if (work.previewBridge && !bridgeReady && !session.soft) session.soft = setTimeout(softAccept, 5000)
            check()
          } catch (error) {
            if (!current(version) || abort.signal.aborted) return
            uncertain = true
            check()
          }
        })()
      }
      const fullscreenButton = dialog.querySelector('[data-preview-fullscreen]')
      const expanded = value => {
        dialog.classList.toggle('is-expanded', value)
        fullscreenButton.setAttribute('aria-pressed', String(value))
        fullscreenButton.setAttribute('aria-label', value ? '退出全屏' : '全屏预览')
      }
      const fullscreen = async () => {
        if (document.fullscreenElement === dialog) { try { await document.exitFullscreen?.() } catch { expanded(false) }; return }
        if (dialog.classList.contains('is-expanded')) { expanded(false); return }
        try {
          if (!dialog.requestFullscreen) throw Error('Fullscreen unavailable')
          await dialog.requestFullscreen()
          if (live === session) expanded(true)
        } catch { if (live === session) expanded(true) }
      }
      const fullscreenChange = () => { if (live === session && !document.fullscreenElement) expanded(false) }
      const escapePreview = () => {
        if (dialog.classList.contains('is-expanded')) {
          if (document.fullscreenElement === dialog) document.exitFullscreen?.().catch(() => {})
          expanded(false)
        } else close()
      }
      document.addEventListener('fullscreenchange', fullscreenChange)
      let listening = true
      const removeDialog = () => {
        if (!listening) return
        listening = false
        document.removeEventListener('fullscreenchange', fullscreenChange)
      }
      session.removeListeners = removeDialog
      dialog.addEventListener('close', removeDialog, {once:true})
      // Native dialog traps focus, including its iframe, without touching background UI.
      dialog.addEventListener('cancel', event => {
        event.preventDefault()
        escapePreview()
      })
      dialog.addEventListener('click', event => {
        const target = event.target.closest('button')
        if (!target) return
        if (target.hasAttribute('data-preview-close')) { removeDialog(); close(); return }
        if (target.hasAttribute('data-preview-refresh')) load(session.work)
        if (target.hasAttribute('data-preview-fullscreen')) fullscreen()
        if (target.hasAttribute('data-preview-continue')) { notice.hidden = true; status.textContent = '未经自动验证的隔离预览；画面异常时可重试或独立打开。' }
        if (target.dataset.previewDevice) {
          viewport.dataset.device = target.dataset.previewDevice
          dialog.querySelectorAll('[data-preview-device]').forEach(button => button.setAttribute('aria-pressed', String(button === target)))
        }
      })
      document.body.style.overflow = 'hidden'
      document.documentElement.style.overflow = 'hidden'
      if (dialog.showModal) dialog.showModal()
      else { dialog.setAttribute('open', ''); dialog.setAttribute('role', 'dialog') }
      dialog.querySelector('[data-preview-close]').focus({preventScroll:true})
      load(work)
    }
    on(root, 'click', event => {
      const explicit = event.target.closest('[data-open-preview]')
      if (explicit) { open(explicit.dataset.openPreview, explicit); return }
    })
    on(window, 'message', event => live?.onMessage?.(event))
    cleanup = () => { listeners.splice(0).forEach(off => off()); delete root.dataset.previewReady }
  }
  window.__fliexProjectPreview = {init, destroy, close}
  document.addEventListener('pjax:send', destroy)
  document.addEventListener('pjax:complete', init)
  document.addEventListener('pjax:error', init)
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true})
  else init()
})()

(() => {
  'use strict'
  if (window.__fliexProjects) { window.__fliexProjects.init(); return }
  let cleanup = () => {}
  const destroy = () => { cleanup(); cleanup = () => {} }
  const init = () => {
    const root = document.querySelector('[data-projects-switcher]')
    if (!root || root.dataset.projectsReady) return
    destroy()
    root.dataset.projectsReady = 'true'
    const tabs = [...root.querySelectorAll('[data-project-tab]')]
    const panels = [...root.querySelectorAll('[data-project-panel]')]
    const list = root.querySelector('[role=tablist]')
    const compact = window.matchMedia('(max-width:1100px)')
    const listeners = []
    const on = (target, name, fn) => {
      target.addEventListener(name, fn)
      listeners.push(() => target.removeEventListener(name, fn))
    }
    const revealTab = tab => {
      if (!compact.matches || !tab) return
      const left = tab.offsetLeft, right = left + tab.offsetWidth
      if (left < list.scrollLeft) list.scrollLeft = left
      else if (right > list.scrollLeft + list.clientWidth) list.scrollLeft = right - list.clientWidth
    }
    const orientation = () => {
      list.setAttribute('aria-orientation', compact.matches ? 'horizontal' : 'vertical')
      revealTab(tabs.find(tab => tab.getAttribute('aria-selected') === 'true'))
    }
    const choose = (index, {animate = true, updateUrl = true} = {}) => {
      const selected = tabs[index]
      if (!selected) return
      tabs.forEach((tab, i) => {
        const active = i === index
        tab.setAttribute('aria-selected', String(active))
        tab.tabIndex = active ? 0 : -1
        panels[i].classList.remove('is-entering')
        panels[i].hidden = !active
      })
      if (animate) panels[index].classList.add('is-entering')
      revealTab(selected)
      if (updateUrl) {
        const heading = panels[index].querySelector('h2[id]')
        // replaceState changes the deep link without scrolling or triggering PJAX.
        try { history.replaceState(history.state, '', '#' + heading.id) } catch {}
      }
    }
    const fromHash = () => {
      let id
      try { id = decodeURIComponent(location.hash.slice(1)) } catch { return }
      const index = panels.findIndex(panel => panel.id === id || panel.querySelector('h2[id]')?.id === id)
      if (index >= 0) choose(index, {animate:false, updateUrl:false})
    }
    tabs.forEach((tab, index) => {
      on(tab, 'click', () => choose(index))
      on(tab, 'keydown', event => {
        const direction = {ArrowDown:1, ArrowRight:1, ArrowUp:-1, ArrowLeft:-1}[event.key]
        if (!direction && !['Home', 'End'].includes(event.key)) return
        event.preventDefault()
        const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + direction + tabs.length) % tabs.length
        tabs[next].focus({preventScroll:true})
        choose(next)
      })
    })
    on(window, 'hashchange', fromHash)
    on(window, 'popstate', fromHash)
    on(compact, 'change', orientation)
    orientation()
    fromHash()
    cleanup = () => {
      listeners.splice(0).forEach(off => off())
      delete root.dataset.projectsReady
    }
  }
  window.__fliexProjects = {init, destroy}
  document.addEventListener('pjax:send', destroy)
  document.addEventListener('pjax:complete', init)
  document.addEventListener('pjax:error', init)
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true})
  else init()
})()
